#include "mesh.h"#include <string.h>#include "256.h"#include "FileStuff.h"#include "BMP.h"void reverse(char *, int);void SpinCursor( int initFlag );Boolean CommandPeriod ( void );OSErr putShadow ( Str255 thePlugFileName, meshHeader theMeshHeader );OSErr putShadow ( Str255 thePlugFileName, meshHeader theMeshHeader ){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	int i, x, y, theMark;	char	*theTexture;	long	theSize, theWidth, theHeight;	int		theMeshSize;									// in sections	sectionInfoEntry *sectionInfo;	 _256Header thePlugHeader;//----------------------------------------------------------------------------------------	// new plug file	theError = FSMakeFSSpec (0L, 0L, thePlugFileName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	theMeshSize = theMeshHeader.meshWidth * theMeshHeader.meshHeight;	theWidth = theMeshHeader.meshWidth * 256;	theHeight = theMeshHeader.meshHeight * 256;	theSize = theWidth * theHeight;	FileRead ( &thePlugHeader, sizeof( _256Header ), thePlugFileRef );	thePlugHeader.sectionInfoOffset += sizeof(struct _256Header);			// add header length to offset	thePlugHeader.paletteOffset += sizeof(struct _256Header);				// ditto	thePlugHeader.colorMapOffset += sizeof(struct _256Header);	sectionInfo = (sectionInfoEntry *) NewPtr ( thePlugHeader.sections * sizeof(sectionInfoEntry) );	if ( sectionInfo == nil ){		FSClose ( thePlugFileRef );		return -1;	}	theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		DisposePtr ( (char *) sectionInfo );		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, thePlugHeader.sectionInfoOffset );	FileRead (sectionInfo, 128 * thePlugHeader.sections, thePlugFileRef );	for( i = 0; i < thePlugHeader.sections; i++ )		sectionInfo[i].offset += (sizeof(struct _256Header) + sizeof(struct textureHeader));	theError = readBMP ( "\p:Graphics.in:shadow.bmp", theWidth, theHeight, nil, theTexture );	if ( theError != noErr ){		DisposePtr ( (Ptr) theTexture );		DisposePtr ( (Ptr) sectionInfo );		FSClose ( thePlugFileRef );		return theError;	}	SpinCursor ( true );	theMark = 0;	for( y = 0; y < 2 * theMeshSize - theMeshHeader.meshWidth; y += (2 * theMeshHeader.meshWidth) ){ // sections y		for(i = 0; i < 256; i++){	// get one line from each section across			if ( CommandPeriod() ){				DisposePtr ( (char *) sectionInfo );				DisposePtr ( theTexture );				FSClose ( thePlugFileRef );				InitCursor();				return noErr; 			}			SpinCursor ( false );			for( x = (2 * theMeshHeader.meshWidth - 1); x >= 1; x -= 2 ){				FileSeek ( thePlugFileRef, sectionInfo[x + y].offset + (i * 256) );				reverse(theTexture + theMark, 256);				FileWrite (theTexture + theMark, 256, thePlugFileRef);				theMark += 256;			}		}	}	DisposePtr ( (char *) sectionInfo );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	InitCursor();	return	noErr;}